import{_ as l,l as r,o as e,c as n,v as t,p as s,x as i,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"标量衍射的适用边界","description":"","frontmatter":{"title":"标量衍射的适用边界","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/scalar-diffraction-bound.md","filePath":"litho/scalar-diffraction-bound.md","lastUpdated":1789023840000}'),E={name:"litho/scalar-diffraction-bound.md"};function c(f,a,m,A,_,u){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="标量衍射的适用边界" tabindex="-1">标量衍射的适用边界 <a class="header-anchor" href="#标量衍射的适用边界" aria-label="Permalink to &quot;标量衍射的适用边界&quot;">​</a></h1><div class="epigraph"><p>标量衍射用单一复振幅 $U$ 代替矢量 $\\mathbf{E}$；当线宽与波长可比、偏振与多层边界变得重要时，必须回到麦克斯韦的全部分量。</p><footer>—— 据 Born &amp; Wolf, Principles of Optics 与 Mack, Fundamental Principles of Optical Lithography 对标量近似的讨论整理</footer></div><p><a href="/litho/coherence-length-prep">上一课</a>说明有限带宽与时间相干。电磁与几何光学课程至此收束于一个判断：后课大量用标量 \\(U\\) 做衍射，何时可信？本课是本课程最后一课。下一课转入 <a href="/litho/mosfet-gate-length">MOSFET 与栅长</a>——器件为何需要图形，而不是把成像积分提前写完。单色波、折射率与光程的课程接口，要等到器件课结束之后的 <a href="/litho/em-wave-index">单色波、折射率与光程</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从 <a href="/litho/maxwell-to-wave">麦克斯韦方程到波动方程</a> 起，有时用矢量（<a href="/litho/polarization-states">偏振</a>、<a href="/litho/fresnel-coefficients">菲涅尔</a>），有时用标量（<a href="/litho/plane-wave-k">平面波</a>、<a href="/litho/thin-lens-equation">透镜方程</a>）。缺口是：什么条件下标量错得不可接受？本课只谈建模层次，不把产线分辨公式当作本课的定理。</p><p>标量默认：偏振可平均或单一、孔径上给定 \\(U\\) 后自由空间传播、薄膜与衬底的矢量耦合已吸进有效边界。这些在低 NA、特征远大于 \\(\\lambda\\) 时常常够用。高 NA、窄缝、金属多层会把 s/p 差异和三维边界抬到一阶。</p><h3 id="标量失败不是「几何光学失败」" tabindex="-1">标量失败不是「几何光学失败」 <a class="header-anchor" href="#标量失败不是「几何光学失败」" aria-label="Permalink to &quot;标量失败不是「几何光学失败」&quot;">​</a></h3><p>几何光学是 \\(\\lambda\\to 0\\) 的光线极限；标量衍射是中间层；矢量电磁是完整层。特征缩小先打破的是几何（要衍射），再在 NA 与材料变极端时打破标量（要矢量）。不要把「要算衍射」与「必须 FDTD」当成同一句话。</p><p><span class="marginnote">Kirchhoff 型标量：孔径上 \\(U\\) 等于未扰动入射再乘透过率。掩模厚度、侧壁与多层会破坏这个假设。Mack 把光学光刻的成像链写在标量 Hopkins 框架里，并明确矢量与三维掩模是修正项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标量：\\(( \\nabla^2+k^2)U=0\\)，给定边界上的 \\(U\\)，用角谱或惠更斯–菲涅尔传播。倾向适用：中低 NA、特征 \\(\\gg\\lambda\\)、偏振对比弱、薄膜已折成有效透过率。失效信号：p/s 反射差显著、窄缝 TE/TM 传播不同、掩模三维阴影、金属色散与等离子体效应。</p><p>矢量：保留 \\(\\mathbf{E}\\)、\\(\\mathbf{H}\\) 与界面条件。严格解用于掩模与薄膜栈的关键图形；全芯片日常仍跑标量，再对库做矢量校正。本课不教求解器，只划边界。</p>',12)),(e(),s(d,null,{default:i(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEO%5B%22%E5%87%A0%E4%BD%95%E5%85%89%E5%AD%A6%20%E7%9F%AD%E6%B3%A2%E6%9E%81%E9%99%90%22%5D%20--%3E%20SCA%5B%22%E6%A0%87%E9%87%8F%20U%20%E8%A1%8D%E5%B0%84%22%5D%0A%20%20SCA%20--%3E%20VEC%5B%22%E7%9F%A2%E9%87%8F%20E%2C%20H%22%5D%0A%20%20FEAT%5B%22%E7%89%B9%E5%BE%81%E3%80%81NA%E3%80%81%E5%81%8F%E6%8C%AF%22%5D%20--%3E%20CHOICE%5B%22%E9%80%89%E5%93%AA%E4%B8%80%E5%B1%82%22%5D%0A%20%20CHOICE%20--%3E%20SCA%0A%20%20CHOICE%20--%3E%20VEC%0A%20%20SCA%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%E6%88%90%E5%83%8F%E4%B8%BB%E7%BA%BF%E7%94%A8%20U%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>历史顺序是：先光线，再标量衍射，再在节点推进后把矢量当校正。日常引擎仍是标量，因为全芯片要快。本课定位：知道何时标量是零阶、何时必须加矢量补丁，而不是在每一处重推麦克斯韦。</p><p>三层次按问题选。画共轭与倍率用几何；算空中像用标量 \\(U\\)；掩模三维与高 NA 偏振用矢量。后一课程从单色 \\(U\\)、折射率与光程重新展开成像，默认读者已经接受这条分层，并且已经知道器件为什么要图形。</p><p>标量失败的典型现场是：同一套光学模型对线和孔的预测偏差方向不同，或 TE/TM 空中像差出一截工艺窗口。那不是「再调一次 \\(k_1\\)」能吸收的，而是模型层级选错。本课把这条经验写成边界，不把求解器当内容。器件课接下来只问图形对象，不再升级麦克斯韦。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教 FDTD 或严格耦合波的实现，也不讨论电子束、纳米压印。抗蚀剂化学、照明部分相干的 Hopkins 交叉系数，属于成像主线，不在本课写完。下一课起解释 MOSFET 栅、CMOS 成对、半节距与节点名——图形化的对象，不是成像公式。</p><p>后课默认：标量 \\(U\\) 是窄带、偏振可控制时的工作马；高 NA 与三维掩模要矢量验证。光学前置课程在此结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>几何 → 标量衍射 → 矢量电磁，按特征、NA 与材料升级，不是越完整越好。</li><li>标量快，适合全芯片；高 NA、三维掩模、强金属层需要矢量。</li><li>本课程不把成像主线写完；下一课改问器件为何要图形。</li><li>单色波与光程在器件课之后才作为成像课程的第一课。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；Born &amp; Wolf, <em>Principles of Optics</em>。</li></ul>',9))])}const T=l(E,[["render",c]]);export{B as __pageData,T as default};
